inline ::flatbuffers::Offset<OPPSurface> CreateOPPSurface(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> ID = 0,
    oppSurfaceKind KIND = oppSurfaceKind::UNSPECIFIED,
    ::flatbuffers::Offset<::flatbuffers::String> MATERIAL = 0,
    oppMaterialClass MATERIAL_CLASS = oppMaterialClass::UNSPECIFIED,
    uint32_t COUNT = 1,
    ::flatbuffers::Offset<OPPProvenance> PROVENANCE = 0,
    ::flatbuffers::Offset<OPPQuantity> AREA = 0,
    ::flatbuffers::Offset<OPPQuantity> MASS = 0,
    ::flatbuffers::Offset<OPPQuantity> SPECULAR_REFLECTIVITY = 0,
    ::flatbuffers::Offset<OPPQuantity> DIFFUSE_REFLECTIVITY = 0,
    ::flatbuffers::Offset<OPPQuantity> ABSORPTIVITY = 0,
    ::flatbuffers::Offset<OPPQuantity> EMISSIVITY = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PANEL_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> GLTF_MATERIAL_NAME = 0,
    int32_t GLTF_MATERIAL_INDEX = -1,
    ::flatbuffers::Offset<::flatbuffers::String> NOTES = 0) {
  OPPSurfaceBuilder builder_(_fbb);
  builder_.add_NOTES(NOTES);
  builder_.add_GLTF_MATERIAL_INDEX(GLTF_MATERIAL_INDEX);
  builder_.add_GLTF_MATERIAL_NAME(GLTF_MATERIAL_NAME);
  builder_.add_PANEL_ID(PANEL_ID);
  builder_.add_EMISSIVITY(EMISSIVITY);
  builder_.add_ABSORPTIVITY(ABSORPTIVITY);
  builder_.add_DIFFUSE_REFLECTIVITY(DIFFUSE_REFLECTIVITY);
  builder_.add_SPECULAR_REFLECTIVITY(SPECULAR_REFLECTIVITY);
  builder_.add_MASS(MASS);
  builder_.add_AREA(AREA);
  builder_.add_PROVENANCE(PROVENANCE);
  builder_.add_COUNT(COUNT);
  builder_.add_MATERIAL(MATERIAL);
  builder_.add_ID(ID);
  builder_.add_MATERIAL_CLASS(MATERIAL_CLASS);
  builder_.add_KIND(KIND);
  return builder_.Finish();
}

