  ::flatbuffers::Offset<OPPAssetRef> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<OPPAssetRef>(end);
    fbb_.Required(o, OPPAssetRef::VT_VAM_ID);
    fbb_.Required(o, OPPAssetRef::VT_VARIANT_ID);
    fbb_.Required(o, OPPAssetRef::VT_ASSET_SHA256);
    return o;
  }
