inline ::flatbuffers::Offset<OPPAssetRef> CreateOPPAssetRef(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> VAM_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> VAM_VERSION = 0,
    ::flatbuffers::Offset<::flatbuffers::String> VAM_CID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> VARIANT_ID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ASSET_SHA256 = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ASSET_CID = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ASSET_FILE_NAME = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ASSET_MEDIA_TYPE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> GLTF_VERSION = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ENTITY_ID = 0,
    bool GEOMETRY_MATCHES_PHYSICAL = false,
    double METERS_PER_ASSET_UNIT = 1.0) {
  OPPAssetRefBuilder builder_(_fbb);
  builder_.add_METERS_PER_ASSET_UNIT(METERS_PER_ASSET_UNIT);
  builder_.add_ENTITY_ID(ENTITY_ID);
  builder_.add_GLTF_VERSION(GLTF_VERSION);
  builder_.add_ASSET_MEDIA_TYPE(ASSET_MEDIA_TYPE);
  builder_.add_ASSET_FILE_NAME(ASSET_FILE_NAME);
  builder_.add_ASSET_CID(ASSET_CID);
  builder_.add_ASSET_SHA256(ASSET_SHA256);
  builder_.add_VARIANT_ID(VARIANT_ID);
  builder_.add_VAM_CID(VAM_CID);
  builder_.add_VAM_VERSION(VAM_VERSION);
  builder_.add_VAM_ID(VAM_ID);
  builder_.add_GEOMETRY_MATCHES_PHYSICAL(GEOMETRY_MATCHES_PHYSICAL);
  return builder_.Finish();
}

